//! The "OPC-UA Server" page: how to connect, why it is not secure, why campus
//! WiFi will not work, and every variable the server publishes.
//!
//! **v2 addition** — v1 had no remote interface, so there is no v1 counterpart to
//! this file.
//!
//! The node table is generated by iterating
//! [`CietSignal::ALL`], [`CietControl::ALL`] and [`CietSwitch::ALL`] from the
//! crate library's `ciet_opcua::node_map`, which is the single source of truth
//! for the address space. It is deliberately **not** hand-copied: a variable
//! added to the server appears here on the next build with no edit to this file.
//!
//! ## Why the warnings are unmissable rather than tucked away
//!
//! The server runs with OPC-UA `SecurityPolicy::None` and anonymous access, and
//! by default binds all interfaces. Every control is writable by anyone who can
//! reach the port — heater power, pump pressure, set points, branch valves. A
//! user who does not understand that could plausibly leave it running on a shared
//! network, so the page states it in plain language rather than as a footnote.

use egui::Ui;

use outram_park_digital_twin_engine::ciet_opcua::node_map::{CietControl, CietSignal, CietSwitch};

use crate::ciet_simulator_v2::CIETApp;
use crate::opcua_startup::OpcuaStatus;

/// Colour of the "no authentication, no encryption" banner text.
///
/// Deliberately a hard red rather than the theme's warning colour: it must read
/// as an alarm in both the light and the dark egui themes.
const WARNING_TEXT_COLOUR: egui::Color32 = egui::Color32::from_rgb(255, 80, 80);

impl CIETApp {
    /// The central panel of the "OPC-UA Server" page.
    ///
    /// Lays out, in order: the endpoint URLs (the LAN one first, because that is
    /// the one a user types into a client on another machine), the security
    /// warning, the server details, the "connecting from another device"
    /// troubleshooting block, and the scrollable node table.
    pub fn ciet_sim_opcua_page(&mut self, ui: &mut Ui) {
        ui.heading("OPC-UA Server (IEC 62541)");
        ui.label(
            "This simulator publishes its plant state over OPC-UA so you can \
             drive it from UaExpert, from a PLC toolchain, from a Python client, \
             or from the bundled ciet_v2_opcua_client.",
        );
        ui.separator();

        match &self.opcua_status {
            OpcuaStatus::Running(handle) => {
                let info = handle.endpoint_info();

                // ---- how to connect -------------------------------------
                ui.heading("Endpoint URL -- type this into your client");

                match &info.lan_url {
                    Some(lan_url) => {
                        ui.label("From another device on this network:");
                        ui.horizontal(|ui| {
                            ui.monospace(format!("{lan_url}"));
                            if ui.button("Copy").clicked() {
                                ui.ctx().copy_text(format!("{lan_url}"));
                            }
                        });
                    }
                    None => {
                        ui.colored_label(WARNING_TEXT_COLOUR, "From another device: UNAVAILABLE.");
                        ui.label(
                            "This machine has no non-loopback network address up, so there \
                             is no URL another device could reach. Join a network -- or start \
                             a phone hotspot and connect this machine to it -- then restart \
                             the simulator.",
                        );
                    }
                }

                ui.add_space(4.0);
                ui.label("On this machine (loopback):");
                ui.horizontal(|ui| {
                    ui.monospace(format!("{}", info.loopback_url));
                    if ui.button("Copy").clicked() {
                        ui.ctx().copy_text(format!("{}", info.loopback_url));
                    }
                });

                ui.separator();

                // ---- the security warning --------------------------------
                if info.bound_to_all_interfaces {
                    ui.colored_label(
                        WARNING_TEXT_COLOUR,
                        "WARNING -- THIS SERVER IS BOUND TO ALL NETWORK INTERFACES",
                    );
                    ui.colored_label(
                        WARNING_TEXT_COLOUR,
                        "There is NO authentication and NO encryption. Anyone on this \
                         network can READ every value AND WRITE every control -- heater \
                         power, CTAH pump pressure, temperature set points, branch valves. \
                         Do NOT run this on untrusted or public WiFi.",
                    );
                    ui.colored_label(
                        WARNING_TEXT_COLOUR,
                        "Restart with `--bind 127.0.0.1` to keep the server on this \
                         machine only.",
                    );
                } else {
                    ui.label(
                        "Bound to a specific address rather than all interfaces. There is \
                         still no authentication and no encryption -- anyone who can reach \
                         this address can read and write everything.",
                    );
                }

                ui.separator();

                // ---- server details --------------------------------------
                ui.heading("Server details");
                egui::Grid::new("opcua_server_details")
                    .num_columns(2)
                    .striped(true)
                    .show(ui, |ui| {
                        ui.label("Security policy");
                        ui.label("None -- anonymous, unauthenticated, unencrypted");
                        ui.end_row();

                        ui.label("Namespace URI");
                        ui.monospace(format!("{}", info.namespace_uri));
                        ui.end_row();

                        ui.label("Variables served");
                        ui.label(format!("{}", info.node_count));
                        ui.end_row();

                        ui.label("PKI directory");
                        ui.monospace(format!("{}", info.pki_dir_display));
                        ui.end_row();
                    });
                ui.label(
                    "The PKI directory exists because the OPC-UA stack expects one. With \
                     security policy None it holds nothing that protects you.",
                );

                ui.separator();

                // ---- getting a second device connected -------------------
                self.opcua_connecting_from_another_device(ui);

                ui.separator();

                // ---- the node table --------------------------------------
                self.opcua_node_table(ui);
            }

            OpcuaStatus::Failed(error) => {
                ui.colored_label(
                    WARNING_TEXT_COLOUR,
                    "The OPC-UA server did not start. The simulation is running anyway; \
                     only the remote interface is unavailable.",
                );
                ui.label("Error reported by the server:");
                ui.monospace(error);
                ui.add_space(4.0);
                ui.label(
                    "The usual cause is the port already being in use -- another OPC-UA \
                     server, or a second copy of this simulator. Quit and restart with a \
                     different port, e.g. `--port 4841`.",
                );
                ui.separator();
                self.opcua_node_table(ui);
            }

            OpcuaStatus::NotStarted => {
                ui.label(
                    "The OPC-UA server was not started for this session. Every page of \
                     the simulator still works; there is simply nothing to connect to.",
                );
                ui.separator();
                self.opcua_node_table(ui);
            }
        }
    }

    /// The right-hand side panel of the "OPC-UA Server" page: a one-glance
    /// summary of where to point a client and what to do if it will not connect.
    pub fn ciet_sim_opcua_page_side_panel(&mut self, ui: &mut Ui) {
        ui.heading("At a glance");

        match &self.opcua_status {
            OpcuaStatus::Running(handle) => {
                let info = handle.endpoint_info();
                ui.label("Server: running");
                ui.label("Connect to:");
                ui.monospace(format!("{}", info.primary_url()));
                ui.add_space(4.0);
                ui.label(format!("{} variables published", info.node_count));
                ui.colored_label(
                    WARNING_TEXT_COLOUR,
                    "No login. No encryption. Every control is writable.",
                );
            }
            OpcuaStatus::Failed(_) => {
                ui.colored_label(WARNING_TEXT_COLOUR, "Server: failed to start");
                ui.label("Try `--port 4841`.");
            }
            OpcuaStatus::NotStarted => {
                ui.label("Server: not started");
            }
        }

        ui.separator();
        ui.label("Cannot connect?");
        ui.label("Campus / enterprise WiFi blocks this. Use a phone hotspot.");
        ui.separator();
        ui.label(
            "Reminder: offline educational demonstration. Never connect this to a real \
             plant, to safety-critical infrastructure, or to institutional production \
             systems.",
        );
    }

    /// The practical "why can't my other laptop see it" block.
    ///
    /// Kept short on purpose so the page stays scannable — a user who cannot
    /// connect should find the answer here rather than conclude the software is
    /// broken.
    fn opcua_connecting_from_another_device(&self, ui: &mut Ui) {
        ui.heading("Connecting from another device");
        ui.label(
            "On campus or enterprise WiFi this will not work -- those networks isolate \
             clients from each other and block mDNS.",
        );
        ui.label(
            "Use a phone hotspot: connect both machines to it and the client will find \
             this simulator automatically. A home router works too.",
        );
        ui.label("If discovery fails, type the URL above into any OPC-UA client by hand.");
        ui.label(
            "The bundled `ciet_v2_opcua_client` binary discovers this server \
             automatically over mDNS -- no address to type -- as long as the network \
             lets mDNS through.",
        );
    }

    /// The scrollable table of every published variable.
    ///
    /// Generated from `ciet_opcua::node_map`, so it cannot drift from the address
    /// space the server actually serves. Columns: display name, the string part
    /// of the `NodeId`, the unit, and whether the variable is read-only (`R`) or
    /// readable and writable (`RW`).
    ///
    /// The namespace index (`ns=`) is assigned by the server at start-up, so it
    /// is not shown per row: resolve the namespace URI listed above, or simply
    /// browse the address space, which is what every OPC-UA client does anyway.
    fn opcua_node_table(&self, ui: &mut Ui) {
        ui.heading("Published variables");
        ui.label(
            "Node ids below are the string part of the OPC-UA NodeId. Combine them with \
             the namespace index your client resolves for the namespace URI above, or \
             just browse the Outputs / Controls folders.",
        );
        ui.label("R = read-only output.   RW = readable and writable control.");
        ui.add_space(4.0);

        egui::ScrollArea::both()
            .auto_shrink([false, false])
            .max_height(320.0)
            .show(ui, |ui| {
                egui::Grid::new("opcua_node_table")
                    .num_columns(4)
                    .striped(true)
                    .show(ui, |ui| {
                        ui.strong("Variable");
                        ui.strong("Node id (string)");
                        ui.strong("Unit");
                        ui.strong("Access");
                        ui.end_row();

                        for signal in CietSignal::ALL {
                            ui.label(signal.display_name());
                            ui.monospace(signal.node_identifier());
                            ui.label(signal.unit());
                            ui.label("R");
                            ui.end_row();
                        }

                        for control in CietControl::ALL {
                            let (minimum, maximum) = control.valid_range();
                            ui.label(control.display_name());
                            ui.monospace(control.node_identifier());
                            ui.label(format!("{} ({} to {})", control.unit(), minimum, maximum));
                            ui.label("RW");
                            ui.end_row();
                        }

                        for switch in CietSwitch::ALL {
                            ui.label(switch.display_name());
                            ui.monospace(switch.node_identifier());
                            ui.label("boolean");
                            ui.label("RW");
                            ui.end_row();
                        }
                    });
            });

        ui.add_space(4.0);
        ui.label(
            "Writes to the continuous controls are clamped to the ranges shown, so an \
             out-of-range write is honoured at the nearest limit rather than pushing the \
             solver somewhere non-physical.",
        );
    }
}
